import React from 'react';
import { Box, Container, Typography, Button } from '@mui/material';
import Slider from 'react-slick';
import 'slick-carousel/slick/slick.css';
import 'slick-carousel/slick/slick-theme.css';
import carouselBg from '../assets/Carousel.png';

const EventsSlider = () => {
  const settings = {
    dots: true,
    infinite: true,
    speed: 500,
    slidesToShow: 1,
    slidesToScroll: 1,
    autoplay: true,
    autoplaySpeed: 5000,
    arrows: true,
    pauseOnHover: true,
  };

  // Örnek veri yapısı
  const slides = [
    {
      id: 1,
      title: "UnityCraft Workshop",
      subtitle: "Ücretsiz öğren, mezun ol, iş fırsatı yakala!",
      type: "Bootcamp",
      deadline: "15.11.2024",
      image: "https://via.placeholder.com/800x400"
    },
    // ... diğer slide'lar
  ];

  return (
    <Box
      sx={{
        backgroundImage: `url(${carouselBg})`,
        backgroundSize: 'cover',
        backgroundPosition: 'center',
        backgroundRepeat: 'no-repeat',
        width: '100%',
        minHeight: '500px',
        py: 4,
        position: 'relative',
      }}
    >
      <Container maxWidth="lg">
        <Slider {...settings}>
          {slides.map((slide) => (
            <Box key={slide.id}>
              <Box
                sx={{
                  display: 'flex',
                  gap: 4,
                  p: 3,
                  backgroundColor: 'rgba(255, 255, 255, 0.95)',
                  borderRadius: '16px',
                  boxShadow: '0 4px 20px rgba(0, 0, 0, 0.1)',
                }}
              >
                <Box
                  sx={{
                    flex: '0 0 50%',
                    '& img': {
                      width: '100%',
                      height: 'auto',
                      borderRadius: '12px',
                    }
                  }}
                >
                  <img src={slide.image} alt={slide.title} />
                </Box>
                
                <Box
                  sx={{
                    flex: '1',
                    display: 'flex',
                    flexDirection: 'column',
                    justifyContent: 'center',
                    gap: 2,
                  }}
                >
                  <Typography variant="h4" component="h2" fontWeight="bold">
                    {slide.title}
                  </Typography>
                  <Typography variant="subtitle1" color="text.secondary">
                    {slide.subtitle}
                  </Typography>
                  <Box sx={{ display: 'flex', gap: 1, my: 2 }}>
                    <Button 
                      variant="contained" 
                      color="primary"
                      sx={{ borderRadius: '20px' }}
                    >
                      {slide.type}
                    </Button>
                    <Button 
                      variant="outlined" 
                      color="primary"
                      sx={{ borderRadius: '20px' }}
                    >
                      İş Fırsatı
                    </Button>
                  </Box>
                  <Typography variant="body2" color="text.secondary">
                    Son Başvuru: {slide.deadline}
                  </Typography>
                  <Button 
                    variant="contained" 
                    color="primary"
                    sx={{ 
                      mt: 2,
                      width: 'fit-content',
                      borderRadius: '8px',
                    }}
                  >
                    Başvur
                  </Button>
                </Box>
              </Box>
            </Box>
          ))}
        </Slider>
      </Container>
    </Box>
  );
};

export default EventsSlider;
